style.css:
@-moz-document domain("instagram.com") {
/* Pure Black Background & Professional Font */
    body, ._as9z, ._aa4b, ._aabd {
        background-color: #000000 !important;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
    }

    /* Mobile-like Slim Feed (Twitter/X Style) */
    main[role="main"] {
        max-width: 600px !important;
        margin: 0 auto !important;
        border-left: 1px solid #2f3336 !important;
        border-right: 1px solid #2f3336 !important;
    }

    /* Hide Sidebar Suggestions (Clutter-free) */
    [role="complementary"], .xvb8j5 {
        display: none !important;
    }

    /* Navigation Bar: Twitter/X Style Icons */
    div[role="navigation"] {
        background-color: #000000 !important;
        border-right: 1px solid #2f3336 !important;
    }

    /* The "Red Box 1" & Stats Helper */
    div[role="navigation"]::after {
        content: "1";
        display: flex;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        margin: 20px auto;
        background: #ff3040;
        color: white;
        font-weight: bold;
        border-radius: 8px;
        box-shadow: 0 0 10px rgba(255, 48, 64, 0.4);
    }

    /* Productivity Tip under the box */
    div[role="navigation"]::before {
        content: "STAY FOCUSED";
        display: block;
        text-align: center;
        font-size: 8px;
        color: #71767b;
        letter-spacing: 1px;
        margin-top: 10px;
        order: 10;
    }

    /* Dynamic Coloring on Interaction */
    a:hover, div[role="button"]:hover {
        background-color: rgba(255, 255, 255, 0.05) !important;
        transition: 0.2s ease;
    }

    /* Simplified Post Borders */
    article {
        border-bottom: 1px solid #2f3336 !important;
        margin-bottom: 0 !important;
        padding-top: 15px !important;
    }
}
